// Recebe o payload do formulário (via node Webhook) e vira 1 linha de Baserow por peça.
// ATENÇÃO: num Code node o $input é a saída do node ANTERIOR (aqui = Config, só tokens).
// O corpo do POST tem que ser lido DIRETO do node Webhook, pelo nome.
// Freios: confere o form_secret (freio leve de spam), teto de 20 itens, e
// só passa URL que tem id do Mercari (mXXXX). Status inicial = Fila (rascunho).
// A linha entra CRUA (só source_url + mercari_id + nota); o /agenda enriquece depois.
const cfg = $('Config').first().json;
const wh = $('Webhook (form do Caio)').first().json;
const payload = (wh && wh.body) ? wh.body : (wh || {});

if (!cfg.form_secret || String(payload.secret).trim() !== String(cfg.form_secret).trim()) {
  throw new Error('unauthorized: secret invalido');
}
const items = Array.isArray(payload.items) ? payload.items : [];
if (items.length === 0) throw new Error('sem itens');
if (items.length > 20) throw new Error('acima do teto de 20 por envio');

const out = [];
for (const it of items) {
  const url = (it && it.url ? String(it.url) : '').trim();
  const note = (it && it.note ? String(it.note) : '').trim();
  const m = url.match(/\/item\/(m\d+)/i) || url.match(/(m\d+)/i);
  if (!m) continue;                 // ignora o que não é item do Mercari
  out.push({ json: {
    mercari_id: m[1],
    source_url: url,
    title_pt: m[1],                 // rótulo provisório; o /agenda troca pelo título traduzido
    tags: note,
    status: 'Fila'
  }});
}
if (out.length === 0) throw new Error('nenhuma URL de Mercari valida');
return out;
